def Strongest_Extension(class_name, extensions):
    def calculate_strength(ext):
        cap = sum(1 for c in ext if c.isupper())
        sm = sum(1 for c in ext if c.islower())
        return cap - sm

    strongest = 0
    result = extensions[0]
    for ext in extensions:
        if calculate_strength(ext) > strongest:
            strongest = calculate_strength(ext)
            result = ext
        elif calculate_strength(ext) == strongest:
            pass  # keep the first one in order
    return f"{class_name}.{result}"
