    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all prime factors of a
    prime_factors = []
    d = 2
    temp = a
    while d * d <= temp:
        while temp % d == 0:
            if d not in prime_factors:
                prime_factors.append(d)
            temp //= d
        d += 1 if d == 2 else 2  # Skip even numbers after 2

    if temp > 1:
        if temp not in prime_factors:
            prime_factors.append(temp)

    # Check if exactly 3 prime factors (counting multiplicity)
    if len(prime_factors) != 3:
        return False

    # Check if all factors are prime (should be true by construction, but verify for safety)
    for p in prime_factors:
        if not is_prime(p):
            return False

    # Verify their product equals a
    product = 1
    for p in prime_factors:
        product *= p
    if product != a:
        return False

    return True
