def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    i = 2
    temp = a
    while temp > 1:
        if temp % i == 0:
            # i is prime
            count += 1
            temp //= i
        else:
            i += 1
    if count != 3:
        return False
    # Check that the three prime factors are distinct
    factors = []
    temp = a
    while temp > 1:
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                factors.append(p)
                temp //= p
                break
        if temp == 1:
            break
        # if temp > 1 after loop, it's a prime factor
        factors.append(temp)
        temp = 1

    if len(set(factors)) != 3:
        return False
    return all(isinstance(f, int) and f >= 2 for f in factors)
