def sum(a, b):
    """
    Return the sum of all common divisors of two positive integers a and b.
    """
    if a <= 0 or b <= 0:
        return 0
    common = 0
    for d in range(1, min(a, b) + 1):
        if a % d == 0 and b % d == 0:
            common += d
    return common
