def sum_common_divisors(a: int, b: int) -> int:
    """Return the sum of all common divisors of a and b."""
    if a <= 0 or b <= 0:
        return 0

    # Find the greatest common divisor (GCD)
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)

    # Sum of all divisors of the GCD
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1

    return total
```

