def is_multiply_prime(a):
    """
    Returns True if the given number 'a' (a < 100) is the product of exactly three prime numbers,
    and False otherwise. This includes counting multiplicities (e.g., 2 * 2 * 7 = 28 is valid,
    but 2 * 3 * 5 = 30 is also valid).

    Note: The problem statement implies we are looking for a representation of 'a' as p1 * p2 * p3
    where p1, p2, p3 are primes. It does not strictly require p1, p2, p3 to be distinct.
    For example:
    - 30 = 2 * 3 * 5 -> True
    - 28 = 2 * 2 * 7 -> True
    - 8 = 2 * 2 * 2 -> True
    - 6 = 2 * 3 (only 2 primes) -> False
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Generate list of primes up to 'a'
    primes = [p for p in range(2, a + 1) if is_prime(p)]

    # Check all combinations of 3 primes (with replacement)
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
                # Optimization: if product exceeds 'a', break (since primes are sorted)
                if primes[i] * primes[j] * primes[k] > a:
                    break
    return False
```

