def recursive_list_sum(lst):
    """
    Recursively flattens nested lists (if any) and returns the sum of all integer elements.

    This implementation assumes the input is a list of lists (potentially nested) containing integers.
    If the input is a flat list of integers, it simply sums them.
    """
    if not isinstance(lst, list):
        raise TypeError("Input must be a list.")

    if not lst:
        return 0

    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        elif isinstance(item, (int, float)):
            total += item
        else:
            raise TypeError(f"Unsupported element type: {type(item).__name__} in nested list.")

    return total
```

