def recursive_list_sum(lst):
    """
    Recursively flattens a nested list structure and sums all numeric elements.

    This function handles nested lists by recursively summing elements at every level.
    It assumes the input contains only lists and numbers (integers or floats).

    Parameters:
    lst (list): A nested list containing numbers and/or sublists

    Returns:
    float: The sum of all numeric elements in the flattened structure
    """
    if not lst:
        return 0

    # Base case: if the current element is a number, add it to the sum
    if isinstance(lst[0], (int, float)):
        return lst[0] + recursive_list_sum(lst[1:])

    # Recursive case: if the current element is a list, flatten and sum recursively
    elif isinstance(lst[0], list):
        # Find the end of the current nested list
        end_index = -1
        for i, item in enumerate(lst):
            if not isinstance(item, list):
                end_index = i
                break

        # Sum all elements in the nested list and continue with the rest
        nested_sum = 0
        for j, item in enumerate(lst):
            if isinstance(item, list):
                nested_sum += recursive_list_sum(item)
            else:
                nested_sum += item

        return nested_sum + recursive_list_sum(lst[end_index+1:])

    else:
        raise TypeError(f"Unsupported element type: {type(lst[0])}")
```

