def encrypt(s):
    """
    Encrypts a string by shifting each alphabetic character down by 4 positions.
    Non-alphabetic characters remain unchanged.
    The shift wraps around the alphabet (e.g., 'y' becomes 'c').
    """
    shift = 4
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            shifted = (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted + ord('a')))
        elif 'A' <= char <= 'Z':
            shifted = (ord(char) - ord('A') + shift) % 26
            result.append(chr(shifted + ord('A')))
        else:
            result.append(char)
    return ''.join(result)
