    Returns True if the given number 'a' (a < 100) is the product of exactly three primes,
    accounting for multiplicity (e.g., 2 * 2 * 7 = 28 is valid, 2 * 3 * 5 = 30 is valid).

    The function checks all combinations of three primes (p1, p2, p3) such that p1 * p2 * p3 == a.
    Primes are allowed to be repeated.
    """
    def is_prime(n):
        """Check if n is a prime number."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Precompute primes up to 'a'
    primes = [p for p in range(2, a + 1) if is_prime(p)]

    # Iterate through all combinations of three primes (with replacement)
    # We use indices i, j, k where i <= j <= k to avoid redundant checks and ensure uniqueness of the set of factors
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                p1 = primes[i]
                p2 = primes[j]
                p3 = primes[k]
                if p1 * p2 * p3 == a:
                    return True
                if p1 * p2 * p3 > a:
                    # Since primes are sorted, further increases in k will also exceed a
                    break
    return False
