def encrypt(s):
    """
    Encrypts a string by shifting each letter in the alphabet down by 4 places.
    Letters outside the alphabet range (e.g., punctuation, spaces) are left unchanged.
    The shift is applied modulo 26 to wrap around the alphabet.
    """
    shift = 4
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            shifted = (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted + ord('a')))
        elif 'A' <= char <= 'Z':
            shifted = (ord(char) - ord('A') + shift) % 26
            result.append(chr(shifted + ord('A')))
        else:
            result.append(char)
    return ''.join(result)
