def encrypt(s):
    """
    Encrypt a string by rotating the alphabet such that each letter
    is shifted down by 4 positions.

    The shift wraps around the alphabet (e.g., 'a' -> 'e', 'z' -> 'd').
    Non-alphabetic characters are left unchanged.
    Both uppercase and lowercase letters are supported.

    Examples:
        encrypt('hi') -> 'lm'
        encrypt('asdfghjkl') -> 'ewhjklnop'
        encrypt('gf') -> 'kj'
        encrypt('et') -> 'ix'
    """
    shift = 4

    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in s)
